/* Payments originate with customers. They never transfer directly between firms. */
function marketNumbers(v){return v.a===v.b?{sales:[100,100],ads:[v.a?40:0,v.b?40:0]}:v.a?{sales:[160,40],ads:[40,0]}:{sales:[40,160],ads:[0,40]}}
function marketBoard(v){if(v.predict)return `<div class="prediction-scene"><div class="prediction-before">A keeps <b>60 coins</b> now</div><div class="prediction-change"><section class="firm-a"><strong>Company A</strong><div class="mini-tv ad-off"><span>ADS OFF</span></div><p>Stops advertising</p></section><section class="firm-b"><strong>Company B</strong><div class="mini-tv ad-on"><span>ADS ON</span></div><p>Keeps advertising</p></section></div><div class="prediction-after"><span>What will A keep?</span><strong>60 <i>→</i> ?</strong></div></div>`;const m=marketNumbers(v);return `<div class="market-board ${v.money===undefined?'introducing':''}" aria-label="Customer payments and advertising costs"><div class="market-customers"><span>Customers</span><div class="customer-crowd" aria-hidden="true">${Array.from({length:10},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div></div><div class="payment-routes" aria-hidden="true"><span class="route route-a">↓</span><span class="route route-b">↓</span></div><div class="market-firms">${[0,1].map(i=>`<section class="market-firm firm-${i?'b':'a'}" data-firm="${i}"><div class="firm-name">Company ${i?'B':'A'}</div><div class="mini-tv ${(i?v.b:v.a)?'ad-on':'ad-off'}"><span>${(i?v.b:v.a)?'ADS ON':'ADS OFF'}</span><i></i></div><div class="customer-share" aria-label="${m.sales[i]/20} of 10 customers">${Array.from({length:m.sales[i]/20},()=>'<i></i>').join('')}</div><div class="money-row income"><span>Sales</span><b data-sales="${i}">${m.sales[i]}</b></div><div class="money-row ad-cost"><span>Ads</span><b data-cost="${i}">−${m.ads[i]}</b></div><div class="money-row kept"><span>Left</span><b data-left="${i}">${m.sales[i]-m.ads[i]}</b><div class="kept-coins" aria-hidden="true">${Array.from({length:(m.sales[i]-m.ads[i])/20},()=>'<i></i>').join('')}</div></section>`).join('')}</div><div class="payment-coins" aria-hidden="true"></div><div class="market-step" role="status">${v.a===v.b?(v.a?'Both pay for ads':'No ad bills'):(v.a?'More customers choose A':'More customers choose B')}</div></div>`}
function playMarketTransition(stage,from,to,isCurrent){
 const target=marketNumbers(to),before=marketNumbers(from);stage.innerHTML=marketBoard(from);stage.classList.add('market-playing');const board=stage.querySelector('.market-board'),status=board.querySelector('.market-step');status.textContent='Watch the ads…';[0,1].forEach(i=>{board.querySelector(`[data-left="${i}"]`).textContent='—';board.querySelector(`[data-firm="${i}"] .kept-coins`).innerHTML='';});
 const later=(fn,ms)=>setTimeout(()=>{if(isCurrent())fn()},ms);
 later(()=>{[0,1].forEach(i=>{const on=i?to.b:to.a,tv=board.querySelector(`[data-firm="${i}"] .mini-tv`);tv.className='mini-tv '+(on?'ad-on':'ad-off');tv.querySelector('span').textContent=on?'ADS ON':'ADS OFF'});status.textContent=to.a===to.b?'Customers split evenly':to.a?'Customers shift toward A':'Customers shift toward B';},300);
 later(()=>{[0,1].forEach(i=>{const share=board.querySelector(`[data-firm="${i}"] .customer-share`);share.innerHTML=Array.from({length:target.sales[i]/20},(_,j)=>`<i style="animation-delay:${j*50}ms"></i>`).join('');share.classList.add('share-arrives')});const coins=board.querySelector('.payment-coins');coins.innerHTML=[0,1].map(i=>Array.from({length:target.sales[i]/20},(_,j)=>`<i class="payment-coin to-${i?'b':'a'}" style="animation-delay:${j*65}ms"></i>`).join('')).join('');status.textContent='Customers pay the companies';},750);
 later(()=>{[0,1].forEach(i=>{board.querySelector(`[data-sales="${i}"]`).textContent=target.sales[i];board.querySelector(`[data-left="${i}"]`).textContent='…';board.querySelector(`[data-firm="${i}"] .kept-coins`).innerHTML='';});},1450);
 later(()=>{[0,1].forEach(i=>{board.querySelector(`[data-cost="${i}"]`).textContent='−'+target.ads[i];const row=board.querySelector(`[data-firm="${i}"] .ad-cost`);row.classList.toggle('bill-paid',target.ads[i]>0);if(target.ads[i])row.insertAdjacentHTML('beforeend','<i class="outgoing-coin"></i><i class="outgoing-coin second"></i>')});status.textContent=target.ads[0]+target.ads[1]?'Ad bills come out next':'No ad bills to pay';},1700);
 later(()=>{[0,1].forEach(i=>{const left=target.sales[i]-target.ads[i];board.querySelector(`[data-left="${i}"]`).textContent=left;const row=board.querySelector(`[data-firm="${i}"] .kept`);row.classList.add('total-arrives');row.querySelector('.kept-coins').innerHTML=Array.from({length:left/20},()=>'<i></i>').join('')});status.textContent=`A keeps ${target.sales[0]-target.ads[0]} · B keeps ${target.sales[1]-target.ads[1]}`;stage.classList.remove('market-playing');},2450);
}
